repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('plaza', 30), ('harbour', 53), ('harbour', 36), ('grand', 48), ('harbour', 9)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.journal.py:
"""A book of bookings with a cached total."""


class BookingBook:
    def __init__(self):
        self._bookings = []
        self._total = None

    def add(self, booking):
        """Add one booking to the book."""
        self._bookings.append(booking)

    def total(self):
        """Return the total nights of the bookings in the book."""
        if self._total is None:
            self._total = sum(x.nights for x in self._bookings)
        return self._total

    def count(self):
        """Return how many bookings the book holds."""
        return len(self._bookings)


def group_by_hotel(bookings):
    """Return a dict from hotel to the list of bookings with that hotel."""
    groups = {}
    for x in bookings:
        groups.setdefault(x.hotel, []).append(x)
    return groups
